const REFS={N5:REF5,N4:REF4};
V.ref=(el,k)=>{
const R=REFS[LV];k=R[k]?k:Object.keys(R)[0];const d=R[k];
el.innerHTML=`<h1>Reference</h1><p class="sub">Quick cheat-sheets · tap a row to hear it</p><div class="tabs">${Object.entries(R).map(([x,v])=>`<a class="chip ${x==k?'on':''}" href="#/ref/${x}">${v.t}</a>`).join('')}</div><input class="search" placeholder="Search…"><div class="tw"><table><thead><tr>${d.h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody></tbody></table></div>`;
const tb=$('tbody',el),inp=$('.search',el),f=()=>{const q=inp.value.toLowerCase();tb.innerHTML=d.r.filter(r=>r.join(' ').toLowerCase().includes(q)).map(r=>`<tr style="cursor:pointer">${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')};
inp.oninput=f;f();
tb.onclick=e=>{const tr=e.target.closest('tr');if(tr){const c=[...tr.children].map(x=>x.textContent);speak(/[぀-ヿ一-鿿]/.test(c[0])?c[0]:c[1]||c[0])}}};

/* ---------- Shell, router, theme ---------- */
const buildNav=()=>{$('#nav').innerHTML=`<a class="logo" href="#/"><b>日</b>Japanese ${LV||''}</a>`+(LV?[['','日','Home'],...vis().map(x=>[x[0],x[1][0],x[2]])].map(([id,ic,t])=>`<a class="nl" data-id="${id}" href="#/${id}"><i>${ic}</i>${t}</a>`).join(''):'')};
const setLv=l=>{LV=l;store.set('lv',l);D={...ALL.shared,...ALL[l]};document.documentElement.dataset.lv=l;$('#lvchip').textContent=l+' ⇄';$('#lvchip').hidden=false;buildNav()};
V.level=el=>{const c=l=>ALL[l].vocab.reduce((a,x)=>a+x.length,0)+' words · '+ALL[l].kanji.length+' kanji · '+ALL[l].grammar.length+' grammar points';
el.innerHTML=`<h1>Choose your level</h1><p class="sub">Pick the JLPT level you want to practise. You can switch any time.</p><div class="grid">${[['N5','Beginner','Kana, basic grammar, everyday words'],['N4','Elementary','Longer sentences, conditionals, passive & causative']].map(([l,t,d],i)=>`<button class="card hv" style="--i:${i}" data-l="${l}"><div class="jp">${l}</div><h3>${t}</h3><p>${d}</p><div class="pt">${c(l)}</div></button>`).join('')}</div>`;
el.onclick=e=>{const b=e.target.closest('[data-l]');if(b){setLv(b.dataset.l);location.hash=='#/'?route():location.hash='#/'}}};
$('#hello').textContent=`Welcome back, ${CFG.name}!`;
$('#foot').textContent=`© 2025 ${CFG.owner}. All rights reserved.`;
const root=document.documentElement;
root.dataset.theme=store.get('theme',matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light');
$('#theme').onclick=()=>{const t=root.dataset.theme=='dark'?'light':'dark';root.dataset.theme=t;store.set('theme',t)};
const closeModal=()=>$('#modal').classList.remove('on');
$('#modal').onclick=e=>{if(e.target.id=='modal')closeModal()};
addEventListener('keydown',e=>{if(e.key=='Escape')closeModal()});
function route(){
cleanups.forEach(f=>f());cleanups=[];closeModal();
const [s='',a,b]=location.hash.slice(2).split('/').map(decodeURIComponent),el=$('#app');
el.onclick=null;el.classList.remove('enter');void el.offsetWidth;el.classList.add('enter');
$$('.nl').forEach(x=>x.classList.toggle('on',x.dataset.id==s));
const ok=LV&&(!SEC.find(x=>x[0]==s)||vis().some(x=>x[0]==s));
(!LV||s=='level'?V.level:ok&&V[s]?V[s]:V.home)(el,a,b);scrollTo(0,0)}
const lv0=store.get('lv',null);if(lv0&&ALL[lv0])setLv(lv0);else buildNav();
addEventListener('hashchange',route);route();
